class Solution {
    public String nextPalindrome(String num) {
        int halfLen = num.length() / 2;
        char[] half = num.substring(0, halfLen).toCharArray();

        int i = halfLen - 2;
        while (i >= 0 && half[i] >= half[i + 1]) i--;
        if (i < 0) return "";

        int j = halfLen - 1;
        while (half[j] <= half[i]) j--;

        char tmp = half[i]; half[i] = half[j]; half[j] = tmp;

        int l = i + 1, r = halfLen - 1;
        while (l < r) {
            char t = half[l]; half[l] = half[r]; half[r] = t;
            l++; r--;
        }

        String newHalf = new String(half);
        String revHalf = new StringBuilder(newHalf).reverse().toString();
        if (num.length() % 2 == 1) {
            return newHalf + num.charAt(halfLen) + revHalf;
        }
        return newHalf + revHalf;
    }
}

