var nextPalindrome = function(num) {
    const halfLen = Math.floor(num.length / 2);
    const half = num.slice(0, halfLen).split('');

    let i = halfLen - 2;
    while (i >= 0 && half[i] >= half[i + 1]) i--;
    if (i < 0) return "";

    let j = halfLen - 1;
    while (half[j] <= half[i]) j--;

    [half[i], half[j]] = [half[j], half[i]];

    let l = i + 1, r = halfLen - 1;
    while (l < r) {
        [half[l], half[r]] = [half[r], half[l]];
        l++; r--;
    }

    const newHalf = half.join('');
    const revHalf = half.reverse().join('');
    if (num.length % 2 === 1) {
        return newHalf + num[halfLen] + revHalf;
    }
    return newHalf + revHalf;
};
